/**  Recoverability classification guiding automated retries vs. user intervention (`P0-T09`). */
export type Recoverability = Recoverability_Serialize | Recoverability_Deserialize;

/**  Recoverability classification guiding automated retries vs. user intervention (`P0-T09`). */
export type Recoverability_Deserialize = 
/**  Transient failure eligible for backoff/jitter retries (optionally respecting `Retry-After`). */
{
	kind: "Transient",
} & ({
	/**  Suggested retry delay in milliseconds when supplied by server or policy. */
	retryAfterMs?: number | null,
} & {
	/**  Suggested retry delay in milliseconds when supplied by server or policy. */
	retry_after_ms?: number | null,
}) | 
/**  Cannot proceed automatically; UI surfaces an actionable control (e.g. Refresh Link). */
{ kind: "UserActionRequired" } | 
/**  Terminal failure for the current attempt (e.g. 404, policy rejection, hash mismatch). */
{ kind: "Permanent" } | 
/**  Automatically mitigated by fallback or self-healing (e.g. single-stream fallback, DB backup restore). */
{ kind: "SelfHealed" } | 
/**  Unexpected internal fault or caught Actor panic isolated from sibling downloads. */
{ kind: "IsolatedBug" };

/**  Recoverability classification guiding automated retries vs. user intervention (`P0-T09`). */
export type Recoverability_Serialize = 
/**  Transient failure eligible for backoff/jitter retries (optionally respecting `Retry-After`). */
{ kind: "Transient"; 
/**  Suggested retry delay in milliseconds when supplied by server or policy. */
retryAfterMs: number | null } | 
/**  Cannot proceed automatically; UI surfaces an actionable control (e.g. Refresh Link). */
{ kind: "UserActionRequired" } | 
/**  Terminal failure for the current attempt (e.g. 404, policy rejection, hash mismatch). */
{ kind: "Permanent" } | 
/**  Automatically mitigated by fallback or self-healing (e.g. single-stream fallback, DB backup restore). */
{ kind: "SelfHealed" } | 
/**  Unexpected internal fault or caught Actor panic isolated from sibling downloads. */
{ kind: "IsolatedBug" };

/**  Overall security risk tier presented inside the Smart Capture Confirmation Dialog. */
export type RiskLevel = 
/**  Magic bytes positively matched the declared file extension (e.g. `PK..` for `.zip`). */
"verified_match" | 
/**  Standard non-executable download with no anomalies detected. */
"safe" | 
/**  Requires user awareness (explicit executable, HTML trap, or cross-origin redirect). */
"caution" | 
/**  High-confidence deception/malware masquerade (`Enter` shortcut locked!). */
"danger";

/**  Specific structured warning flags surfaced in localized Arabic/English UI banners. */
export type SecurityWarningKind = 
/**  Server returned an HTML web/ad/countdown page (`<!DOCTYPE html>` / `text/html`) for a non-HTML file. */
"html_trap" | 
/**  Executable binary (`MZ`/`MSCF`/`ELF`) or double-extension (`*.mp4.exe`) masquerading as media/docs. */
"executable_masquerade" | 
/**  Declared file extension is directly executable or scriptable on Windows (`.exe`, `.msi`, `.bat`, ...). */
"high_risk_executable" | 
/**  Download redirected from an unrelated referrer page host onto a different origin host (common on ad sites). */
"cross_origin_ad_redirect" | 
/**  Raw filename attempted Unicode Bidi (`RTLO U+202E`) or zero-width extension spoofing (`TH-30`). */
"bidi_filename_spoofing" | 
/**  Weaponized shortcut/help/ClickOnce/script smuggling vector (`.lnk`, `.chm`, `.application`, `<script` in `.svg` — `TH-30`). */
"weaponized_script_or_shortcut" | 
/**  Mountable Windows virtual disk container (`.iso`, `.img`, `.vhd`, `.vhdx`) requiring extra caution (`TH-30`). */
"mountable_disk_image";

